type BuildTuple<N extends number> =
  Recur<N, []>;
type Recur<N extends number, Acc extends unknown[]> =
  Acc['length'] extends N ? Acc : [unknown, ...Recur<N, [unknown, ...Acc]>];
// recursive call wrapped in [unknown, ...] -> not tail position
